\section*{Problem: The Surjective Prime-Bridge Walk}

\textbf{Category:} Spectral Graph Theory / Inclusion-Exclusion

\textbf{Definitions:}
Let $V = \{1, 2, 3, 4, 5, 6\}$ be the set of available digits.
We define a directed graph $G = (V, E)$ where a transition from digit $u$ to digit $v$ is valid (denoted $u \to v$) if and only if their sum is a \textbf{Prime Number}:
\[ (u, v) \in E \iff (u + v) \in \{2, 3, 5, 7, 11\} \]
(Note: $u$ and $v$ can be the same digit if $2u$ is prime, e.g., $1+1=2$. However, we assume standard digits distinctness for adjacency is NOT required unless specified. In this problem, \textbf{self-loops are allowed} if the sum condition is met).

\textbf{The Sequence:}
We consider sequences of length $n=8$, denoted as $S = (d_1, d_2, \dots, d_8)$, where each $d_i \in V$.

\textbf{Constraints:}
A sequence $S$ is valid if it satisfies \textbf{all} of the following:

\begin{enumerate}
    \item \textbf{Prime-Bridge Connectivity:}
    Every pair of adjacent digits must satisfy the graph transition rule.
    \[ \forall i \in \{1, \dots, 7\}, \quad (d_i + d_{i+1}) \in \mathbb{P} \text{ (The set of primes)} \]

    \item \textbf{Boundary Condition:}
    The sequence must start with digit \textbf{1} and end with digit \textbf{6}.
    \[ d_1 = 1, \quad d_8 = 6 \]

    \item \textbf{Surjectivity (The Hard Constraint):}
    The sequence must contain \textbf{every} digit from the set $V$ at least once.
    \[ \{d_1, d_2, \dots, d_8\} = \{1, 2, 3, 4, 5, 6\} \]
\end{enumerate}

\textbf{Question:}
Calculate the total number of such valid sequences.

\end{document}

